# Let me take a step back and write a working transform function
# based on what I've learned from the demo:

# Rules observed from Demo 1:
# 1. Two sections (MR, BM) are exactly unchanged - they're "rubber band" and "diamond" patterns
# 2. One section (MM) gains 1 point - vertical line becomes L-shape
# 3. One section (BR) loses 1 corner point that's an "outlier"

# For the TEST input, I need to apply similar logic

def transform_section(section):
    """
    Transform a 4x4 section.
    Returns transformed section as list of lists.
    """
    size = 4
    non_zero = [(r, c) for r in range(size) for c in range(size) if section[r][c] > 0]

    if not non_zero:
        return section  # Empty section stays empty

    # Determine pattern type
    cols = set(c for r, c in non_zero)
    rows = set(r for r, c in non_zero)

    if len(rows) == 1:  # Horizontal line
        # Transform: create vertical-ish or diamond shape
        r = rows.pop()
        # Add perpendicular point(s)
        result = [(r, c) for c in cols] | {(r, 0), (r, size-1)}
    elif len(cols) == 1:  # Vertical line (like MM)
        c = cols.pop()
        # Add point perpendicular to center
        mid_r = size // 2
        result = [(r, c) for r in rows] | {(mid_r, 0)}
    elif len(non_zero) <= 5:  # Small isolated pattern (like rubber band)
        # Keep identity
        result = non_zero
        for r in range(size):
            for c in range(size):
                sec[r][c] = 0
        for r, c in result:
            sec[r][c] = 4
    elif len(non_zero) > 6:  # Large scattered pattern (like BR)
        # Remove outlier points
        result = remove_outlier_points(non_zero, section)
        for r in range(size):
            for c in range(size):
                section[r][c] = 0
        for r, c in result:
            section[r][c] = 4
    else:
        # Medium pattern - keep identity
        result = non_zero

    # Reconstruct full section (all non-zero cells)
    for r in range(size):
        for c in range(size):
            if (r, c) in result:
                section[r][c] = 4
            else:
                section[r][c] = 0

    return section

def remove_outlier_points(points, section_grid):
    """Remove points that are corners of the bounding box but have fewer neighbors"""
    result = set(points)

    # Find bounding box
    min_r, max_r = min(r for r, c in points), max(r for r, c in points)
    min_c, max_c = min(c for r, c in points), max(c for r, c in points)

    # Check corner points
    corners = [(min_r,min_c), (min_r,max_c), (max_r,min_c), (max_r,max_c)]
    for r, c in corners:
        if (r, c) in points:
            # Count neighbors (adjacent points)
            neighbors = 0
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                if (r+dr, c+dc) in points:
                    neighbors += 1
            # If isolated corner (no neighbors), remove it
            if neighbors < 2:
                result.remove((r, c))

    return result

