def has_4_x_4_pattern(points, rows=3, cols=5):
    """Check if points form a compact 4x4-like pattern"""
    if len(points) < 4:
        return False
    # Use bounding box check: points should be confined to ~4x4 area
    min_r, max_r = min(p[0] for p in points), max(p[0] for p in points)
    min_c, max_c = min(p[1] for p in points), max(p[1] for p in points)
    height = max_r - min_r + 2  # +2 for buffer
    width = max_c - min_c + 2
    # Compact pattern: fits in 4x5 box and has ~4-5 points
    if height <= 4 and width <= 5 and 4 <= len(points) <= 5:
        filled_ratio = (height * width)
        return True
    return False

def complete_l_shapes_and_remove_outliers(grid):
    """Apply both rules: complete L-shapes, remove distant outliers"""
    result = [row[:] for row in grid]

    # Rule 1: Section-based L-shape completion in small sections (3-5 pts in 4x4)
    row_bands = [(0,4), (6,10), (12,16), (18,22)]
    col_bands = [(0,4), (6,10), (12,16), (18,22)]

    def count_points_in_2x2(section, r, c):
        return sum(1 for v in [section[r][c], section[r][c+1], section[r+1][c], section[r+1][c+1]] if v != 0)

    def complete_l_shapes(section):
        result = [row[:] for row in section]
        size = len(section)
        for r in range(size-1):
            for c in range(size-1):
                cnt = count_points_in_2x2(result, r, c)
                if cnt == 3:
                    vals = [result[r][c], result[r][c+1], result[r+1][c], result[r+1][c+1]]
                    zeros = [i for i, v in enumerate(vals) if v == 0]
                    if zeros:
                        i_missing = zeros[0]
                        color = next((v for v in [result[r][c], result[r][c+1]] if v != 0))
                        if color == 0:
                            color = 4  # default for color 4 sections
                        if i_missing == 0: result[r][c] = color
                        elif i_missing == 1: result[r+1][c] = color
                        elif i_missing == 2: result[r][c+1] = color
                        elif i_missing == 3: result[r+1][c+1] = color
        return result

    # Apply L-shape completion
    for r_start, r_end in row_bands:
        for c_start, c_end in col_bands:
            section = [result[r][c_start:c_end+1] for r in range(r_start, r_end+1)]
            completed = complete_l_shapes(section)
            for r in range(len(completed)):
                for c in range(len(completed[0])):
                    result[r_start+r][c_start+c] = completed[r][c]

    # Rule 2: Remove outliers in scattered patterns (6+ points)
